// scripts/lesson_complete/lib/page.mjs — render and validate the lesson page.
//
// Sources: template.html + styles.css + math.js + app.js + content.json.
// index.html and preview/index.html are generated byte-for-byte copies, so the
// raw.githack review link and the local file:// page show the same bytes.

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const require = createRequire(import.meta.url);
const MATH = require("../math.js");

export const TOKENS = ["{{STYLES_CSS}}", "{{CONTENT_JSON}}", "{{MATH_JS}}", "{{APP_JS}}"];
const FORBIDDEN_ABSOLUTE = /https?:\/\//i;

export function readSources(root = ROOT) {
  const read = (name) => readFileSync(join(root, name), "utf8");
  return {
    template: read("template.html"),
    styles: read("styles.css"),
    math: read("math.js"),
    app: read("app.js"),
    content: JSON.parse(read("content.json")),
  };
}

export function validateContent(content) {
  const errors = [];
  if (!content || content.schema !== "soko.lesson_complete/1") {
    errors.push("schema must be soko.lesson_complete/1");
  }
  if (!Array.isArray(content?.questions) || content.questions.length !== 3) {
    errors.push("content.questions must hold exactly three questions");
    return errors;
  }
  const expected = new Map([
    ["q1", { kind: "choice", epsilon: 0.22, choices: [4, 5, 10] }],
    ["q2", { kind: "boolean", epsilon: 0.22, choices: [true, false] }],
    ["q3", { kind: "choice", epsilon: 0.1, choices: [10, 11, 21] }],
  ]);
  for (const question of content.questions) {
    const spec = expected.get(question.id);
    if (!spec) {
      errors.push(`unexpected question id: ${question.id}`);
      continue;
    }
    if (question.kind !== spec.kind) errors.push(`${question.id}: kind must be ${spec.kind}`);
    if (question.epsilon !== spec.epsilon) errors.push(`${question.id}: epsilon must be ${spec.epsilon}`);
    if (JSON.stringify(question.choices) !== JSON.stringify(spec.choices)) {
      errors.push(`${question.id}: choices must be ${JSON.stringify(spec.choices)}`);
    }
    if (!question.choices.includes(question.answer)) errors.push(`${question.id}: answer is not one of the choices`);
    if (typeof question.hint !== "string" || !question.hint.trim()) errors.push(`${question.id}: hint is required`);
    if (/[\r\n]/.test(question.hint || "")) errors.push(`${question.id}: hint must be a single line`);
    if (typeof question.explanation !== "string" || !question.explanation.trim()) {
      errors.push(`${question.id}: explanation is required`);
    }
    if (!question.wrong || typeof question.wrong !== "object") {
      errors.push(`${question.id}: wrong-answer copy is required`);
    }
    if (question.id === "q2") {
      if (question.answer !== false) errors.push("q2: N = 4 is not enough, so the answer must be false");
      if (!(1 / 4 >= 0.22)) errors.push("q2: the reference inequality 1/4 >= 0.22 no longer holds");
    } else {
      const computed = MATH.computeN(question.epsilon);
      if (question.answer !== computed) {
        errors.push(`${question.id}: answer ${question.answer} disagrees with N = ${computed}`);
      }
    }
  }
  return errors;
}

export function renderPage(sources = readSources()) {
  const { template, styles, math, app, content } = sources;
  const errors = validateContent(content);
  if (errors.length) throw new Error("content contract failed:\n  " + errors.join("\n  "));

  for (const token of TOKENS) {
    const count = template.split(token).length - 1;
    if (count !== 1) throw new Error(`template.html must contain ${token} exactly once (found ${count})`);
  }
  if (/<\/script\s*>/i.test(math) || /<\/script\s*>/i.test(app)) {
    throw new Error("inlined JS must not contain a literal closing script tag");
  }
  if (/<\/style\s*>/i.test(styles)) throw new Error("styles.css must not contain a literal closing style tag");

  const json = JSON.stringify(content).replace(/</g, "\\u003c");
  let html = template
    .replace("{{STYLES_CSS}}", () => styles)
    .replace("{{CONTENT_JSON}}", () => json)
    .replace("{{MATH_JS}}", () => math)
    .replace("{{APP_JS}}", () => app);

  const stripped = html.replaceAll("http://www.w3.org/2000/svg", "");
  if (FORBIDDEN_ABSOLUTE.test(stripped)) {
    throw new Error("rendered page contains an absolute http(s) URL");
  }
  if (!html.endsWith("\n")) html += "\n";
  return html;
}

export function sha256(buffer) {
  return createHash("sha256").update(buffer).digest("hex");
}

export function buildLesson({ root = ROOT, write = true, check = false } = {}) {
  const sources = readSources(root);
  const html = renderPage(sources);
  const bytes = Buffer.from(html, "utf8");
  const index = join(root, "index.html");
  const preview = join(root, "preview", "index.html");
  const previous = existsSync(index) ? readFileSync(index) : null;
  const previousPreview = existsSync(preview) ? readFileSync(preview) : null;
  const drift = !previous || !previous.equals(bytes) || !previousPreview || !previousPreview.equals(bytes);

  if (write && !check) {
    writeFileSync(index, bytes);
    mkdirSync(dirname(preview), { recursive: true });
    writeFileSync(preview, bytes);
  }

  return {
    ok: !check || !drift,
    drift,
    check,
    bytes: bytes.length,
    sha256: sha256(bytes),
    index,
    preview,
    identical: write && !check
      ? readFileSync(preview).equals(readFileSync(index))
      : Boolean(previous && previousPreview && previous.equals(previousPreview)),
    previousBytes: previous ? previous.length : 0,
  };
}
